interface Cache<K,V> {
  get(key: K): V | undefined
  set(key: K, value: V): void
  swapStrategy(name: string): void
}

interface EvictionStrategy<K,V> {
  onAccess(key: K, value: V): void
  onInsert(key: K, value: V): void
